INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(65000, 65, 0, 1, 0, 0, 0, 0, 'Dragonblight', 'For millennia the Great Dragonblight has been the heart of Northrend: forests ringing a vast arctic waste littered with the gleaming bones of dead dragons. Dragons near the end of their lives come here, by instinct, to die and enrich the land with their passing.\n\nMalygos'' blue flight guards the bones jealously, but the Scourge has taken many of them anyway, to raise as frost wyrms. It was on the edge of the Dragonblight, too, that the Lich King first loosed his plague upon a human village, years before the Third War.', 'warcraft.wiki.gg: Dragonblight (introduction, Description from site, Rise of the Lich King)'),
(65001, 65, 1, 1, 0, 0, 0, 0, 'Wyrmrest Temple', 'An ancient titan structure, tier after tier of white columns and golden domes towering over the Dragon Wastes. The keepers raised it so that the newly made dragonflights would have a place to meet, a sanctuary and a symbol of their unity. Legend says the Aspects were blessed within it.\n\nHere Alexstrasza, the Life-Binder, has gathered the Wyrmrest Accord of the red, bronze, green and black flights'' envoys, against the blue flight''s war on magic.', 'warcraft.wiki.gg: Wyrmrest Temple (introduction, Ancient times)'),
(65002, 65, 1, 2, 0, 0, 0, 0, 'The Dragonshrines', 'Five shrines surround the temple, each blessed by its flight. The Ruby shrine is an island of green life in the waste, grown, Nozdormu says, from a single drop of Alexstrasza''s blood that melted through the snow and became the Crimson Oak. The Bronze shrine is an impossibly warm oasis of shifting sand where Nozdormu keeps vigil among the dead, like a pocket of a sunnier past. The Azure is a fissure pouring magic into the air; the Obsidian, a blasted place of burning trees at the foot of a volcano. Only the Emerald shrine is untouched by the Scourge.', 'warcraft.wiki.gg: Ruby Dragonshrine; warcraft.wiki.gg: Bronze Dragonshrine; warcraft.wiki.gg: Azure Dragonshrine; warcraft.wiki.gg: Obsidian Dragonshrine; warcraft.wiki.gg: Emerald Dragonshrine'),
(65003, 65, 1, 3, 0, 0, 0, 0, 'Galakrond''s Rest', 'A skeleton half emerged from the ice, far larger than any dragon in living memory: Galakrond, the progenitor of dragonkind, who fell here. Near this place the five proto-dragons who defeated him were made into the Aspects. The Cult of the Damned has come to dig him up and raise him as a frost wyrm.', 'warcraft.wiki.gg: Galakrond''s Rest; warcraft.wiki.gg: Dragonblight (Prehistory)'),
(65004, 65, 1, 4, 0, 0, 0, 0, 'Agmar''s Hammer', 'The Horde''s stronghold in the Dragonblight, held by the Kor''kron under Overlord Agmar, built in the new, more aggressive style of the Horde. Nearby lies Icemist Village, the taunka capital, overrun by nerubians boiling up out of Azjol-Nerub through the Pit of Narjun.', 'warcraft.wiki.gg: Agmar''s Hammer; warcraft.wiki.gg: Icemist Village; warcraft.wiki.gg: Pit of Narjun'),
(65005, 65, 1, 5, 0, 0, 0, 0, 'Wintergarde Keep', 'The Alliance''s fortress in the east of the Dragonblight, built by the Valiance Expedition in the mountains above Wintergarde Village, whose people welcomed it in. The Scourge has struck at it from Naxxramas, floating overhead: the village is now the Carrion Fields, a breeding ground for undead, and the Scourge has found its way into the keep''s crypt, its mine and its lower town.', 'warcraft.wiki.gg: Wintergarde Keep; warcraft.wiki.gg: Carrion Fields'),
(65006, 65, 1, 6, 0, 0, 0, 0, 'Venomspite', 'A Forsaken town in the east, where the Hand of Vengeance carries on its plague experiments.', 'warcraft.wiki.gg: Venomspite'),
(65007, 65, 1, 7, 0, 0, 0, 0, 'Stars'' Rest', 'A night elf outpost with a moonwell, built in Highborne ruins by Commander Saia Azuresteel''s forces, helped by frost nymphs of the nearby forest. In the Highborne gardens of Moonrest, the blue dragons'' attempts to turn the ley lines have woken long-dormant Highborne spirits.', 'warcraft.wiki.gg: Stars'' Rest; warcraft.wiki.gg: Moonrest Gardens'),
(65008, 65, 1, 8, 0, 0, 0, 0, 'Moa''ki Harbor', 'The largest settlement the tuskarr have left since losing Kaskala, its sky always fluttering with bright kites, full of trade, friendly talk and storytellers. Not far away, Indu''le Village was destroyed when magic poured out of the ley line under its lake; the blue dragons'' work. Its dead linger as ghosts, and the ancients of the Lothalor woods have been driven mad.', 'warcraft.wiki.gg: Moa''ki Harbor; warcraft.wiki.gg: Indu''le Village; warcraft.wiki.gg: Lothalor Woodlands'),
(65009, 65, 1, 9, 0, 0, 0, 0, 'New Hearthglen', 'The fortress of the Scarlet Onslaught, the remnant of the Scarlet Crusade, raised in record time on the coast where its fleet made landfall after fleeing Tyr''s Hand: walls, barracks, chapels, and a massive white cathedral. High General Brigitte Abbendis leads it, at war with the Scourge and anyone else who stands in its way. Its soldiers have fortified the cave where Frostmourne once lay, for reasons no one knows.', 'warcraft.wiki.gg: New Hearthglen; warcraft.wiki.gg: Scarlet Point'),
(65010, 65, 1, 10, 0, 0, 0, 0, 'Frostmourne Cavern', 'Here, on an altar encased in ice, the runeblade once lay, with an inscription: "Whomsoever takes up this blade shall wield power eternal. Just as the blade rends flesh, so must power scar the spirit." Arthas and Muradin came here hunting Mal''Ganis. Arthas took up the sword, and the ice that held it struck Muradin down.', 'warcraft.wiki.gg: Frostmourne Cavern; warcraft.wiki.gg: Dragonblight (Rise of the Lich King)'),
(65011, 65, 1, 11, 0, 0, 0, 0, 'Angrathar the Wrathgate', 'A towering wall of saronite knife edges barring the way into Icecrown. Highlord Bolvar Fordragon''s Alliance army holds Fordragon Hold at its foot, and the Horde''s Kor''kron Vanguard stands beside it under Dranosh Saurfang, son of the High Overlord. The battle at the gate is meant to be the first great blow against the Lich King, and the first in which the Horde and Alliance fight side by side.', 'warcraft.wiki.gg: Angrathar the Wrathgate; warcraft.wiki.gg: Fordragon Hold; warcraft.wiki.gg: Kor''kron Vanguard'),
(65012, 65, 1, 12, 0, 0, 0, 0, 'The Path of the Titans', 'A vast ruined road running from Ulduar in the Storm Peaks across Crystalsong Forest and the Dragonblight to Wyrmrest Temple, then on south into the Frozen Sea. North of it, the Crystal Vice cuts deep into the glacier, dragon skeletons jutting from its walls.', 'warcraft.wiki.gg: Path of the Titans; warcraft.wiki.gg: Crystal Vice'),
(65013, 65, 1, 13, 0, 0, 0, 0, 'Nozzlerust Post', 'A goblin trading post selling weapons, materials and food to both the Alliance and the Horde, and stripping the land around it to do so.', 'warcraft.wiki.gg: Nozzlerust Post'),
(65014, 65, 1, 14, 0, 0, 0, 0, 'Jintha''kalar', 'An ancient city of the Drakkari ice trolls, sacked by the Scourge, its people raised to serve it. The pass beyond leads to Zul''Drak.', 'warcraft.wiki.gg: Jintha''kalar'),
(65015, 65, 1, 15, 0, 0, 0, 0, 'Naxxramas', 'The necropolis of Kel''Thuzad, floating over the Carrion Fields. When the Horde and Alliance pushed into the Dragonblight, it appeared above them, the Scourge''s first great counterattack.', 'warcraft.wiki.gg: Naxxramas; warcraft.wiki.gg: Dragonblight (Wrath of the Lich King)'),
(65050, 65, 3, 1, 0, 0, 0, 0, 'The Battle of Angrathar', 'At the Wrathgate, the Alliance and Horde fought side by side, and the Lich King himself came out to face them. Then, from the cliffs, the Forsaken of Grand Apothecary Putress loosed their New Plague on everyone on the field: Scourge, Horde and Alliance alike. Bolvar Fordragon and Dranosh Saurfang were among the fallen. The Lich King, nearly overcome himself, barely escaped back through the gate.\n\nThe red dragons came from Wyrmrest and burned the field clean of the plague and the undead, and where their fire passed, grass and flowers grew.', 'warcraft.wiki.gg: Angrathar the Wrathgate (Wrath of the Lich King)');
